        id: 'ts-se-10',
        title: '光ファイバの接続（融着・メカニカルスプライス）',
        emoji: '🔥',
        body: `▼ゼロから：光ファイバ工事の品質は「接続」で決まると言ってよいほど、接続は重要な工程です。ガラス同士をつなぐ方法は大きく3つ。電気放電でガラスを溶かして一体化する「融着接続」、V溝で軸を合わせて機械的に固定する「メカニカルスプライス」、着脱可能な「コネクタ接続」です。それぞれ損失の大きさ・作業性・用途が異なり、試験では損失の大小関係と作業手順・注意事項が問われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 融着接続（最も低損失な永久接続）
━━━━━━━━━━━━━━━━━━━━━━
融着接続は、光ファイバ端面同士を突き合わせ、アーク放電で加熱溶融して一体化する方法です。
○ 接続損失が最も小さい（単心で0.1dB以下が目安）★
○ 反射がほとんどなく、長期信頼性が高い
× 融着接続機（電源）が必要で、着脱はできない永久接続
手順：外被除去 → 被覆除去 → 清掃 → ファイバカッタで端面を直角に切断 → 融着接続機にセットし放電融着 → 画面で接続状態を確認 → 補強スリーブを加熱収縮して補強。
★端面の切断品質が損失を左右します。切断角度の不良・端面の汚れは高損失の主因。また融着部は裸のガラスなので、必ず補強スリーブで保護します。テープ心線は多心一括融着が可能です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 メカニカルスプライス（電源不要の簡易接続）
━━━━━━━━━━━━━━━━━━━━━━
メカニカルスプライスは、V溝を持つ素子の中で両ファイバ端面を突き合わせ、クランプで機械的に固定する接続です。突合せ部には屈折率整合剤を充てんし、ガラスと空気の境界での反射・損失を抑えます。
○ 工具のみで接続でき電源不要 → 融着接続機を使いにくい現場・災害復旧・宅内工事に便利★
× 接続損失は融着より大きい（0.2〜0.5dB程度が目安）
× 長期信頼性・反射特性は融着に劣る
→ 「メカニカルスプライスは融着より低損失」という記述は×。損失の大小関係（融着＜メカニカル＜コネクタ）は最頻出です。

【図解】光ファイバ接続3方式の比較
　方式｜接続損失の目安｜特徴
　融着接続｜約0.1dB以下｜最も低損失・永久接続・要電源★
　メカニカルスプライス｜約0.2〜0.5dB｜電源不要・整合剤使用★
　コネクタ接続｜約0.3〜0.5dB｜着脱可能・機器接続用
　⇒ 損失は融着が最小、着脱できるのはコネクタのみ
　⚠ 融着部は補強スリーブで必ず保護する

━━━━━━━━━━━━━━━━━━━━━━
🔑 接続損失が生じる原因
━━━━━━━━━━━━━━━━━━━━━━
接続損失の原因は2群に分けられます。
・軸ずれ・角度ずれ・端面間隔・端面品質：施工技量・器具に起因（外的要因）
・コア径やモードフィールド径の不一致・偏心：ファイバ自体の差（内的要因）
★特にシングルモードはコアが約9μmと細いため、わずかな軸ずれでも損失が急増します。融着接続機は画像処理でコア軸を自動調心し、推定損失を表示します。接続後はOTDRで接続点損失を測定し、規定値以内であることを確認します。
⚠ 切断したファイバ屑はガラス片で危険。専用容器に回収し、皮膚に刺さらないよう取り扱います。融着機の放電部やアルコール清掃時の火気にも注意します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「メカニカルスプライスは融着接続より接続損失が小さい」→ ×。融着が最小。
・「メカニカルスプライスには屈折率整合剤を用いる」→ ○。
・「融着接続部は補強不要」→ ×。補強スリーブで保護必須。
・「融着は着脱を繰り返す箇所に適する」→ ×。永久接続。着脱はコネクタ。
・「端面の切断角度不良は接続損失増加の原因になる」→ ○。

★ここだけ暗記：損失の序列は融着（0.1dB以下）＜メカニカル（整合剤・電源不要）＜コネクタ（着脱可）。融着手順は「除去→切断→融着→確認→補強」。SMFは軸ずれに敏感、接続後はOTDRで確認。`,
