        emoji: '🧯',
        body: `▼ゼロから：送信機とアンテナの間で高周波電力を運ぶ線路を給電線と呼びます。代表は同軸ケーブルと導波管。同軸は扱いやすく万能ですが、周波数が高くなるほど損失が増えます。マイクロ波の大電力になると、中空の金属管の中を電波として通す「導波管」の方が低損失です。給電線は「送った電力をいかに減らさずアンテナへ届けるか」が全てで、試験では損失特性・特性インピーダンス・導波管の性質・施工上の注意が問われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 同軸ケーブル給電線
━━━━━━━━━━━━━━━━━━━━━━
・構造：中心導体＋絶縁体＋外部導体（シールド）＋外被の不平衡線路
・特性インピーダンス：無線系は50Ω、テレビ受信系は75Ωが標準★。機器・コネクタと整合させないと反射が生じる
・損失特性：周波数が高いほど、ケーブルが細いほど、長いほど損失大★。大電力・長距離では低損失の太径ケーブル（発泡絶縁など）を選定
・施工：許容曲げ半径の遵守、コネクタの確実な取付けと防水、垂直区間の自重対策（適切な間隔の固定）、雷対策（接地・SPD）
例題：損失0.1dB/mの同軸を30m使うと損失3dB——送信電力の半分が熱として失われます。給電線をいかに短くするかが設計の急所で、これが「無線機をアンテナ直下へ置く（RRH化・タワートップアンプ）」流れの理由です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 導波管給電線
━━━━━━━━━━━━━━━━━━━━━━
導波管は、断面が方形や円形の中空金属管で、内部空間を電磁波がモードを作って伝搬します。
○ マイクロ波帯で同軸より損失が小さく、大電力に耐える★
・遮断周波数：管の寸法で決まる下限周波数があり、それ以下の周波数は伝搬できない★（低い周波数ほど大きな管が必要）
・内部の結露・浸水は損失増・放電の原因になるため、乾燥空気や窒素を封入して内圧を保つ（加圧・防湿）★
・施工：フランジ接続面の平滑・清浄・確実な締付け、規定の曲げ（専用ベンド部品）、機械的応力を与えない支持
→ 「導波管はどんな低い周波数でも使える」は×。遮断周波数以下は通りません。「同軸よりマイクロ波での損失が大きい」も×です。

【図解】同軸ケーブルと導波管の比較
　項目｜同軸ケーブル｜導波管
　構造｜中心導体＋外部導体｜中空の金属管★
　マイクロ波での損失｜大きめ｜小さい○
　特記事項｜50Ω/75Ωの整合｜遮断周波数あり・防湿加圧★
　⇒ 高周波・大電力ほど導波管が有利
　⚠ 導波管内部の結露防止に乾燥空気等を封入する

━━━━━━━━━━━━━━━━━━━━━━
🔑 整合と損失管理
━━━━━━━━━━━━━━━━━━━━━━
・給電系は送信機出力端からアンテナ給電点まで、インピーダンスを一貫して整合させる。不整合点があると反射（次節のVSWR）が生じ、電力が戻ってくる
・接続点（コネクタ・フランジ）は損失・反射の主要発生点。数を減らし、施工品質を確保する
・竣工時は給電系の挿入損失とVSWR（またはリターンロス）を測定して記録★。経年劣化（浸水・腐食）の監視基準にもなる
・屋外の同軸は紫外線・水分で劣化するため、防水処置と定期点検が保全の要
→ 「損失は測らなくても計算値でよい」は×。施工品質（コネクタ・曲げ）で実損失は変わるため実測が原則です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「同軸ケーブルの損失は周波数が高いほど大きい」→ ○。
・「無線機用同軸の標準特性インピーダンスは75Ωである」→ ×。無線系は50Ω（75Ωはテレビ受信系）。
・「導波管には遮断周波数があり、それ以下は伝搬しない」→ ○。
・「導波管はマイクロ波帯で同軸より損失が大きい」→ ×。小さい。
・「導波管内の結露防止のため乾燥空気を封入する」→ ○。
・「給電線はできるだけ長く引き回すのがよい」→ ×。損失最小化のため短く。

★ここだけ暗記：同軸＝50Ω（無線）/75Ω（TV）・高周波ほど損失大・短く太く。導波管＝中空管・マイクロ波で低損失・遮断周波数あり・乾燥空気で防湿。接続点は損失と反射の巣。竣工時に損失とVSWRを実測記録。`,
