・無線連携の場合は病棟全域の電波カバー（サイトサーベイ）とローミング設計、医療機器への電波影響配慮
・親機の応答不能時のバックアップ（副親機・転送先）を設定
・改修工事では稼働中の病棟でシステムを止められないため、切替手順・仮設運用の計画が施工管理の腕の見せ所⚠
