        body: `▼ゼロから：通信機器は電気がなければただの箱です。通信ビル・データセンタ・基地局の通信装置の多くは、商用の交流100V/200Vではなく「直流48V」で動いています。なぜ直流か？——蓄電池を直結できるからです。商用電源が止まった瞬間、何の切替動作もなしに蓄電池が給電を引き継ぎ、通信は一瞬も途切れません。この「整流器＋蓄電池の浮動充電方式」が通信用電源の心臓部で、試験では直流48V採用の理由と浮動充電の仕組みが最重要論点です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 直流−48V給電の理由
━━━━━━━━━━━━━━━━━━━━━━
・蓄電池と直結できる：停電時に無瞬断で蓄電池給電へ移行★（交流給電のような切替時間ゼロ）
・48V程度なら安全性（感電リスク）と電流の大きさ（電圧が低いほど大電流→太い導体）のバランスがよい
・通信用は大地に対して−48V（正極接地）を用いるのが伝統：ケーブル腐食（電食）の抑制に有利とされる★
・構成：商用交流 → 整流器（交流を直流に変換）→ 直流分電盤 → 通信装置、この母線に蓄電池が並列接続★
→ 「停電時に切替装置で蓄電池へ切り替える」は×。並列接続だから切替え不要、が本質です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 浮動充電方式（フロート）
━━━━━━━━━━━━━━━━━━━━━━
浮動充電方式では、整流器が「負荷への給電」と「蓄電池の自己放電を補う微小充電」を同時に行います。
・平常時：整流器が負荷電流＋蓄電池の維持充電を負担。蓄電池は満充電状態で待機★
・停電時：蓄電池が無瞬断で負荷へ放電
・復電時：整流器が負荷給電と蓄電池の回復充電（均等充電等）を行う
・整流器は複数台並列＋予備（N+1冗長）で、1台故障でも所要容量を確保する設計が標準★
例題：負荷電流200A、蓄電池の保持時間3時間が要求のとき、必要な蓄電池容量は 200×3＝600Ah（実際は放電特性・温度・経年劣化係数を加味して選定）。
→ 浮動充電＝「常に並列でつながったまま」がキーワード。停電時「切替」型のUPSとの違いとして問われます。

【図解】通信用直流電源の構成
　機器｜役割｜ポイント
　整流器｜交流→直流変換・充電｜N+1冗長構成★
　蓄電池｜停電時の無瞬断給電｜母線に常時並列接続★
　直流分電盤｜負荷への配電・保護｜回路ごとにヒューズ/遮断器
　⇒ 長時間停電には発電機を組み合わせる
　⚠ −48V（正極接地）は電食抑制などの理由による

━━━━━━━━━━━━━━━━━━━━━━
🔑 蓄電池の種類と保守
━━━━━━━━━━━━━━━━━━━━━━
・鉛蓄電池：通信用の主力。制御弁式（MSE等：補水不要・密閉形）と ベント形（液式）★。設置スペース・耐震架台・換気（水素ガス対策）に配慮
・リチウムイオン電池：小型軽量・高エネルギー密度で採用拡大。充放電管理（BMS）と防火対策が要件
・アルカリ蓄電池：堅牢・長寿命だが用途限定的
・保守：電圧・内部抵抗・温度の定期測定、寿命（期待寿命は温度に強く依存。高温ほど短寿命⚠）管理、更新計画
・容量試験（放電試験）で実力を確認し、保持時間の要求を満たすことを確認する
→ 「蓄電池は設置後無保守でよい」は×。劣化監視と更新が通信の生命線を守ります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「通信用直流電源は停電時に無瞬断で蓄電池給電に移行できる」→ ○。
・「浮動充電方式では蓄電池は負荷と切り離して保管される」→ ×。母線に常時並列。
・「整流器は交流を直流に変換する」→ ○。
・「整流器はN+1冗長構成とするのが一般的」→ ○。
・「制御弁式鉛蓄電池は定期的な補水が必要」→ ×。補水不要が特徴。
・「蓄電池の寿命は周囲温度が高いほど長くなる」→ ×。高温ほど短寿命。
・容量計算（負荷電流×保持時間）は数値問題で出ます。

★ここだけ暗記：通信装置＝直流−48V。整流器（AC→DC・N+1）＋蓄電池（常時並列・浮動充電）で停電も無瞬断。容量＝電流×時間に劣化係数。制御弁式は補水不要、高温は寿命短縮。「切替えない」から強い。`,
