        body: `▼ゼロから：通信ケーブルの経路上に川や鉄道があったら？　自前で橋を架けるわけにはいかないので、既にある橋梁にケーブルを「添架」させてもらいます。また、自前の電柱を建てる代わりに電力会社の柱に通信線を「共架」させてもらうのも日常的な手法です。どちらも「他者の構造物を借りる」工事であり、技術基準だけでなく、施設管理者との協議・許可という手続き面が試験の重要論点になります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 橋梁添架
━━━━━━━━━━━━━━━━━━━━━━
橋梁添架は、道路橋等の桁側面・床版下などに管路・ケーブルを取り付けて渡す方式です。
・手続き：橋梁管理者（道路管理者等）への添架許可申請・占用許可が必須★。添架位置・工法・荷重は管理者と協議して決める
・設計の要点：
　・橋の伸縮への追従：橋梁は温度で伸縮するため、伸縮継手部にはケーブル・管路にも可とう性のある伸縮対応（エキスパンション部の余長・可とう管）を設ける★
　・振動・たわみ対策：車両通行の振動に耐える支持金具・支持間隔
　・環境：日射（管内温度上昇）・凍結・塩害（海上橋）への配慮、景観
　・落下防止：金具の腐食対策と定期点検⚠
・添架が不可能な場合は、河底横断（推進工法等）や水底ケーブル、無線区間（対岸間の無線化）も比較検討する
→ 「橋梁添架は管理者への手続きなしで施工できる」は当然×。協議と許可が第一歩です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 電柱への共架
━━━━━━━━━━━━━━━━━━━━━━
共架は、電力会社等の既設電柱に通信ケーブルを架設することです。
・手続き：電柱所有者との共架契約・申請、1本ごとの可否判定（柱の強度・空き位置）★
・技術基準：
　・取付位置：通信線は電力線（低圧・高圧）の下方に施設★
　・離隔距離：高圧線・低圧線との規定離隔を確保（作業安全と混触防止）★
　・地上高：道路横断部5m以上など、路面からの高さ規定
　・柱の強度：共架による荷重・不平衡張力を検討し、必要に応じ支線補強
・作業安全：電力線接近作業となるため、感電防止（活線接近限界・防護管・電力会社との連絡調整）が最重要⚠
→ 「通信線を電力線の上方に架ける」「離隔は任意」はいずれも×。下方・規定離隔が鉄則です。

【図解】添架・共架の要点
　項目｜橋梁添架｜電柱共架
　手続き｜橋梁管理者の許可・占用｜柱所有者との契約・申請★
　技術の要｜伸縮継手部の可とう対応｜電力線下方・離隔確保★
　安全の要｜高所・水上作業・落下防止｜感電防止・防護管⚠
　⇒ 他者の構造物を借りる＝協議・許可・基準遵守が前提
　⚠ 無許可施工・基準違反は撤去・事故につながる

━━━━━━━━━━━━━━━━━━━━━━
🔑 施工管理の視点
━━━━━━━━━━━━━━━━━━━━━━
・事前調査：橋梁の形式・既設添架物の状況、電柱の空き位置・既設共架線、現地の作業条件（交通量・河川条件）
・工程調整：許可・契約の取得期間を工程に織り込む（手続きが長期化しやすい)★
・施工時：橋上・水上作業の墜落防止（親綱・フルハーネス）、河川上作業の安全（増水時中止基準）、道路上作業の交通規制
・完成後：添架・共架設備の台帳管理と定期点検（金具腐食・張力・離隔の維持）。所有者側の設備更新（橋の補修・電柱の建替え）への追従移設も運用上発生する⚠
→ 「借り物」設備は、作って終わりではなく、貸主との関係管理・点検・移設対応まで含めた生涯管理が必要です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「橋梁添架には橋梁管理者の許可が必要」→ ○。
・「橋梁の伸縮継手部では管路・ケーブルに可とう性を持たせる」→ ○。
・「共架通信線は電力線の上方に施設する」→ ×。下方。
・「共架にあたり電柱の強度検討は不要」→ ×。荷重・張力を検討。
・「電力線接近作業では防護管等の感電防止措置を講じる」→ ○。
・「道路横断部の通信線の地上高は5m以上を確保する」→ ○。

★ここだけ暗記：添架・共架＝「借りる工事」→協議・許可・契約が先行。橋は伸縮対応と落下防止、柱は電力線の下方・離隔・強度検討・感電防止。手続き期間を工程に見込み、完成後も台帳・点検・移設対応。`,
